{
  "userId": "{{user_id}}",
  "name": "Journey product links",
  "description": "Shared App Store, Play Store, website, and a 7-day attribution window.",
  "isDefault": false,
  "settings": {
    "defaultIosUrl": "https://apps.apple.com/app/id1234567890",
    "defaultAndroidUrl": "https://play.google.com/store/apps/details?id=com.example.app",
    "defaultWebFallbackUrl": "https://example.com/products",
    "defaultAttributionWindowHours": 168,
    "utmParameters": {
      "source": "template",
      "medium": "shared",
      "campaign": "product-links"
    },
    "targetingRules": {
      "devices": [
        "ios",
        "android",
        "web"
      ]
    },
    "expiresAfterDays": 90
  }
}
